UPDATE conversation_event_display
SET status = 'PREPARING', attempt_count = 0,
    next_retry_at = NULL, failure_reason = NULL, lease_owner = NULL, lease_until = NULL,
    summary = NULL, content_length = NULL, total_segments = NULL,
    truncated = 0, detail_available = 0, gmt_modified = #{now}
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND turn_id = #{turnId}
  AND dispatch_attempt = #{dispatchAttempt}
  AND event_seq = #{eventSeq}
  AND status = 'FAILED'
  AND source_removed = 0


UPDATE conversation_event_display
SET next_retry_at = NULL,
    attempt_count = CASE WHEN lease_until IS NOT NULL AND lease_until >= #{now}
        THEN LEAST(attempt_count, 0) - 1 ELSE 0 END,
    failure_reason = NULL,
    queue_class = #{queueClass}, gmt_modified = #{now}
WHERE tenant_id = #{tenantId} AND conversation_id = #{conversationId}
  AND turn_id = #{turnId} AND dispatch_attempt = #{dispatchAttempt} AND event_seq = #{eventSeq}
  AND status = 'PREPARING' AND source_removed = 0

mapper.insert:
INSERT IGNORE INTO conversation_event_display
(tenant_id, conversation_id, turn_id, dispatch_attempt, event_seq, event_type, status,
 queue_class, projection_version, attempt_count, gmt_create, gmt_modified)
SELECT e.tenant_id, e.conversation_id, e.turn_id, e.dispatch_attempt, e.event_seq, e.event_type,
       'PREPARING', CASE WHEN e.chunk_count > 1 OR OCTET_LENGTH(e.payload_fragment) > 16384
           THEN 'LARGE' ELSE #{queueClass} END,
       #{projectionVersion}, 0, e.gmt_create, e.gmt_create
FROM agent_conversation_turn_event e
WHERE e.tenant_id = #{tenantId}
  AND e.conversation_id = #{conversationId}
  AND e.turn_id = #{turnId}
  AND e.dispatch_attempt = #{dispatchAttempt}
  AND e.event_seq = #{eventSeq}
ORDER BY e.chunk_index ASC
LIMIT 1

mapper.update:
UPDATE conversation_event_display
SET status = 'FAILED', publication_seq = #{publicationSeq}, failure_reason = #{failureReason},
    lease_owner = NULL, lease_until = NULL, next_retry_at = NULL, gmt_modified = #{now}
WHERE id = #{id} AND status = 'PREPARING' AND attempt_count = #{expectedAttempt}
  AND lease_owner = #{owner} AND lease_until >= #{now}

UPDATE conversation_event_display
SET queue_class = #{toClass}, gmt_modified = #{now}
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND turn_id = #{turnId}
  AND status = 'PREPARING'
  AND queue_class = #{fromClass}

UPDATE conversation_event_display
SET lease_owner = NULL, lease_until = NULL
WHERE id = #{id} AND lease_owner = #{owner}

