UPDATE conversation_event_display
SET status = 'FAILED', publication_seq = #{publicationSeq}, summary = NULL,
    total_segments = 0, truncated = 0, detail_available = 0,
    failure_reason = #{failureReason}, lease_owner = NULL, lease_until = NULL,
    next_retry_at = NULL, gmt_modified = #{now}
WHERE id = #{id}

