SELECT * FROM conversation_event_display
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND turn_id = #{turnId}
  AND status IN ('READY', 'FAILED')
  AND publication_seq IS NOT NULL
  AND publication_seq > #{afterSeq}
ORDER BY publication_seq ASC
LIMIT #{limit}

SELECT COUNT(*) FROM conversation_event_display
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND turn_id = #{turnId}
  AND status = #{status}

SELECT MAX(publication_seq) FROM conversation_event_display
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND turn_id = #{turnId}
  AND publication_seq IS NOT NULL

